  "modify": "değiştirmek",
  "conduct": "yürütmek",
  "terminate": "sonlandırmak",
  "stabilize": "dengelemek",
  "process": "işlemek",
  "restrict": "sınırlandırmak",
  "alter": "değiştirmek",
  "expose": "ifşa etmek",
