function buildKonnektorLesson1Exercises(unitId, lessonId) {
  const shuffle = (arr) => [...arr].sort(() => 0.5 - Math.random());

  const interleaveQuestions = (questions) => {
    if (questions.length <= 1) return questions;
    const buckets = {};
    questions.forEach(q => {
      if (!buckets[q.type]) buckets[q.type] = [];
      buckets[q.type].push(q);
    });
    const result = [];
    let lastType = null;
    while (true) {
      let bestType = null;
      let maxCount = 0;
      for (let type in buckets) {
        if (type !== lastType && buckets[type].length > maxCount) {
          maxCount = buckets[type].length;
          bestType = type;
        }
      }
      if (!bestType) {
        for (let type in buckets) {
          if (buckets[type].length > maxCount) {
            maxCount = buckets[type].length;
            bestType = type;
          }
        }
      }
      if (!bestType || buckets[bestType].length === 0) break;
      const q = buckets[bestType].shift();
      result.push(q);
      lastType = q.type;
      if (buckets[bestType].length === 0) delete buckets[bestType];
    }
    return result;
  };

  const cleanEn = (text) => text ? text.replace(/<strong>/g, "").replace(/<\/strong>/g, "") : "";
  const cleanConnector = (conn) => conn ? conn.replace(/<strong>/g, "").replace(/<\/strong>/g, "") : "";

  const buildMCQuestion = (s, id, allSentences) => {
    const tr = s.tr;
    const candidates = allSentences.filter(item => item.tr !== tr);
    const distractors = shuffle(candidates).slice(0, 3).map(c => c.tr);
    const choices = shuffle([tr, ...distractors]);
    const cleanSentence = cleanEn(s.en);
    return {
      id: id,
      type: "multiple-choice",
      prompt: `Cümlenin en uygun Türkçe karşılığını seçin:<br><br><strong>"${cleanSentence}"</strong>`,
      options: choices,
      correctIndex: choices.indexOf(tr),
      isEngToTr: true,
      enSentence: cleanSentence,
      explanation: s.explanation
    };
  };

  const buildClozeQuestion = (s, id) => {
    const correctVal = cleanConnector(s.connector);
    const cleanSentence = cleanEn(s.en);
    const shuffledOptions = shuffle(s.options.map(cleanConnector));
    const cleanWord = correctVal.replace(/[,.]/g, "").trim();
    let clozedSentence = cleanSentence.replace(new RegExp("\\b" + cleanWord + "\\b", "i"), "___");
    if (!clozedSentence.includes("___")) {
      clozedSentence = cleanSentence.replace(correctVal, "___");
    }
    return {
      id: id,
      type: "fill-blank-dropdown",
      prompt: "Boşluğa gelecek en uygun konnektörü seçin:",
      sentence: clozedSentence,
      options: shuffledOptions,
      correctIndex: shuffledOptions.indexOf(correctVal),
      translation: s.tr,
      explanation: s.explanation
    };
  };

  const buildWBQuestion = (s, id) => {
    const cleanBlocks = s.blocks.map(b => cleanConnector(b));
    const distractors = ["and", "but", "so", "or"];
    const allWords = shuffle([...cleanBlocks, ...distractors]);
    const cleanSentence = cleanEn(s.en);
    return {
      id: id,
      type: "word-bank",
      prompt: "Cümle bloklarını doğru sıraya koyarak İngilizce akademik cümleyi oluşturun:",
      translation: s.tr,
      words: allWords,
      correctOrder: cleanBlocks,
      enSentence: cleanSentence,
      isEngToTr: false,
      explanation: s.explanation
    };
  };

  const buildTransQuestion = (s, id) => {
    const cleanSentence = cleanEn(s.en);
    return {
      id: id,
      type: "translation-text",
      prompt: `"${cleanSentence}" ifadesini Türkçe'ye çevirin:`,
      enSentence: cleanSentence,
      correctSentence: s.tr,
      isEngToTr: true,
      explanation: s.explanation
    };
  };

  const compileExercise = (sentences, exId, title, desc) => {
    const sorted = [...sentences].sort((a, b) => a.en.length - b.en.length);
    const exList = [];

    if (sorted.length >= 5) {
      exList.push({
        id: `u${unitId}l${lessonId}_${exId}_match`,
        type: "matching",
        prompt: "İfadeleri Türkçe karşılıklarıyla eşleştirin.",
        pairs: sorted.slice(0, 5).map(s => ({ left: s.tr, right: cleanEn(s.en) }))
      });
    }

    for (let i = 0; i < Math.min(5, sorted.length); i++) {
      exList.push(buildClozeQuestion(sorted[i], `u${unitId}l${lessonId}_${exId}_cloze_${i}`));
    }

    for (let i = 0; i < Math.min(5, sorted.length); i++) {
      exList.push(buildMCQuestion(sorted[i], `u${unitId}l${lessonId}_${exId}_mc_${i}`, sorted));
    }

    for (let i = 2; i < Math.min(6, sorted.length); i++) {
      exList.push(buildWBQuestion(sorted[i], `u${unitId}l${lessonId}_${exId}_wb_${i}`));
    }

    const transList = sorted.slice(-2).map((s, idx) => buildTransQuestion(s, `u${unitId}l${lessonId}_${exId}_tr_${idx}`));

    return {
      id: `u${unitId}l${lessonId}${exId}`,
      title: title,
      description: desc,
      questions: [...interleaveQuestions(exList), ...transList]
    };
  };

  const compileContrastsExercise = () => {
    const list = unit22Lesson1Contrasts.map((q, idx) => {
      return {
        id: `u${unitId}l${lessonId}_ex4_cloze_${idx}`,
        type: "fill-blank-dropdown",
        prompt: "Boşluğa gelecek en uygun konnektörü seçin:",
        sentence: q.sentence.replace(/_+/g, "___"),
        options: q.options,
        correctIndex: q.options.indexOf(q.correct),
        explanation: q.explanation
      };
    });
    return {
      id: `u${unitId}l${lessonId}ex4`,
      title: "Alıştırma 4: Söz Dizimsel Karşılaştırmalar",
      description: "Connektörlerin söz dizimsel kurallarına (isim öbeği, tam cümle ve noktalama) göre kullanım farklılıkları",
      questions: list
    };
  };

  return [
    compileExercise(unit22Lesson1PhraseRaw, "ex1", "Alıştırma 1: Söz Dizimsel İşlevler — Kategori A (İsim Alan Bağlaçlar (Phrase Connectors))", "Because of ve Despite gibi isim öbeği alan bağlaçların kullanımı"),
    compileExercise(unit22Lesson1ClauseRaw, "ex2", "Alıştırma 2: Söz Dizimsel İşlevler — Kategori B (Cümle Alan Bağlaçlar (Clause Connectors))", "Because ve Although gibi tam cümle alan bağlaçların kullanımı"),
    compileExercise(unit22Lesson1SentenceRaw, "ex3", "Alıştırma 3: Söz Dizimsel İşlevler — Kategori C (Geçiş Kelimeleri (Sentence Connectors))", "Therefore ve However gibi bağımsız cümleleri bağlayan zarfların kullanımı"),
    compileContrastsExercise()
  ];
}

