function buildLessonExercises(lessonId) {
  const sPool = unit11RedesignedSentences[lessonId.toString()];
  const qBasit = buildUnit11RedesignedExercise(sPool.basit, 11, lessonId, 1, "basit");
  const qOrta = buildUnit11RedesignedExercise(sPool.orta, 11, lessonId, 1, "orta");
  const qIleri = buildUnit11RedesignedExercise(sPool.ileri, 11, lessonId, 1, "ileri");
  
  return [
    {
      id: `u11l${lessonId}ex1`,
      title: getLessonTitle(lessonId),
      description: getLessonDesc(lessonId),
      questions: [...qBasit, ...qOrta, ...qIleri]
    }
  ];
}

function getLessonTitle(lessonId) {
  switch(lessonId) {
    case 32: return "Alıştırma 1: Pozitif Edilgen Mastar Modalları";
    case 33: return "Alıştırma 1: Olumsuz Edilgen Mastar Modalları";
    case 34: return "Alıştırma 1: Soru Biçimindeki Edilgen Modallar";
    case 35: return "Alıştırma 1: Eyleyeni Belirtilen Edilgen Modallar (by + Agent)";
    case 36: return "Alıştırma 1: Bölünmüş Edilgen Fiiller (Split Passives)";
    case 37: return "Alıştırma 1: Karmaşık ve Bölünmüş Edilgen Yapılar";
    default: return "Alıştırma 1: Edilgen Yapılar";
  }
}

function getLessonDesc(lessonId) {
  switch(lessonId) {
    case 32: return "Olumlu edilgen modal (can/must/should/will be + V3) yapılarının pratikleri.";
    case 33: return "Olumsuz edilgen modal (cannot/must not/should not be + V3) pratikleri.";
    case 34: return "Soru biçimlerindeki edilgen modal (Can/Should/Must ... be + V3) pratikleri.";
    case 35: return "Eylemi gerçekleştirenin (by + Özne) belirtildiği karmaşık edilgen modal cümleleri.";
    case 36: return "Edilgen fiil arasına zarf giren (is/was + adverb + V3) bölünmüş yapıların pekiştirilmesi.";
    case 37: return "Karmaşık eyleyenli ve zarf bölünmeli edilgen modal yapıların kombine edildiği ileri seviye pratikler.";
    default: return "Edilgen mastar ve bölünmüş edilgen yapı pratikleri.";
  }
}

