// Dynamic karma evaluation injection removed
const excludedKarmaTopicIds = [];
rawTopics.forEach(topic => {
  topic.originalNumLessons = topic.numLessons;
});

let displayLessonCounter = 1;
rawTopics.forEach((topic, uIdx) => {
  let unitTitle = topic.title || "";
  let unitDesc = topic.desc || "";
  let unitPages = null;

  const pageRegex = /\(Sayfa\s*(\d+(?:-\d+)?)\)/i;

  if (unitTitle) {
    const pageMatch = unitTitle.match(pageRegex);
    if (pageMatch) {
      unitPages = pageMatch[1];
    }
    unitTitle = unitTitle
      .replace(/\s*\(Sayfa\s*\d+(?:-\d+)?\)/gi, "")
      .replace(/^[IVXLCDM]+\.\s*/, "")
      .replace(/Takımları/g, "Yapıları")
      .replace(/takımları/g, "yapıları")
      .replace(/Takımı/g, "Yapısı")
      .replace(/takımı/g, "yapısı")
      .replace(/Strüktürleri/g, "Yapıları")
      .replace(/strüktürleri/g, "yapıları")
      .replace(/Strüktürü/g, "Yapısı")
      .replace(/strüktürü/g, "yapısı")
      .replace(/Strüktürel/g, "Yapısal")
      .replace(/strüktürel/g, "yapısal")
      .replace(/Strüktür/g, "Yapı")
      .replace(/strüktür/g, "yapı");
  }
  if (unitDesc) {
    const pageMatch = unitDesc.match(pageRegex);
    if (pageMatch && !unitPages) {
      unitPages = pageMatch[1];
    }
    unitDesc = unitDesc
      .replace(/\s*\(Sayfa\s*\d+(?:-\d+)?\)/gi, "")
      .replace(/takımları/g, "yapıları")
      .replace(/takımlı/g, "yapılı")
      .replace(/takımı/g, "yapısı")
      .replace(/strüktürleri/g, "yapıları")
      .replace(/strüktürel/g, "yapısal")
      .replace(/strüktür/g, "yapı");
  }

  const unitId = topic.id !== undefined ? topic.id : (uIdx + 1);
  const startLessonId = topic.startLessonId !== undefined ? topic.startLessonId : (topic.id !== undefined ? topic.id * 10 : (uIdx + 1) * 10);
  const numLessons = topic.numLessons;
  const unitLessonIds = [];
  for (let l = 0; l < numLessons; l++) {
    let lId = startLessonId + l;
    if (unitId === 1 && l === 7) lId = 901;
    if (unitId === 6 && l === 4) lId = 906;
    if (unitId === 2 && l === 1) lId = 902;
    if (unitId === 15 && l === 1) lId = 915;
    if (unitId === 8 && l === 2) lId = 908;
    if (unitId === 8 && l === 2) lId = 908;
    unitLessonIds.push(lId);
  }

  // Üniteyi oluştur
  units.push({
    id: unitId,
    originalIndex: topic.originalIndex,
    title: unitTitle,
    description: unitDesc,
    lessons: unitLessonIds,
    pages: unitPages,
    edits: topic.edits || []
  });

  for (let lIdx = 0; lIdx < numLessons; lIdx++) {
    let lessonId = startLessonId + lIdx;
    if (unitId === 1 && lIdx === 7) lessonId = 901;
    if (unitId === 6 && lIdx === 4) lessonId = 906;
    if (unitId === 2 && lIdx === 1) lessonId = 902;
    if (unitId === 15 && lIdx === 1) lessonId = 915;
    if (unitId === 8 && lIdx === 2) lessonId = 908;
    if (unitId === 8 && lIdx === 2) lessonId = 908;

    // Ders indeksine göre soruları dinamik oluştur veya doğrudan soru listesini ekle
    const questions = [];
    let lessonExercises = null;
    const unitSentsObj = unitSentencesMap[unitId];

    const isLastReviewLesson = (topic.originalNumLessons !== undefined && topic.numLessons > topic.originalNumLessons) && (lIdx === numLessons - 1);

    if (isLastReviewLesson) {
      const qPool = [];
      for (let prevL = 1; prevL <= topic.originalNumLessons; prevL++) {
        const prevData = unitSentsObj ? unitSentsObj[prevL] : null;
        if (prevData) {
          if (Array.isArray(prevData)) {
            prevData.forEach(item => {
              if (item.en && item.tr) qPool.push(item);
            });
          } else if (prevData.exercises) {
            prevData.exercises.forEach(ex => {
              if (ex.questions) {
                ex.questions.forEach(q => qPool.push(q));
              }
            });
          }
        }
      }
      lessonExercises = buildUnitReviewExercises(unitId, lessonId, qPool);
    } else if (unitSentsObj && unitSentsObj[lIdx + 1]) {
      const data = unitSentsObj[lIdx + 1];
      if (data && typeof data === 'object' && !Array.isArray(data) && data.exercises) {
        // Ders altında birden fazla alıştırma (exercise) tanımlanmış
        lessonExercises = data.exercises.map(ex => ({
          id: ex.id,
          title: ex.title,
          description: ex.description || "",
          questions: ex.questions || [],
          createdAt: ex.createdAt
        }));
      } else if (Array.isArray(data) && data.length > 0) {
        if (unitId === 60) {
          lessonExercises = generateUnit60Exercises(lessonId, data);
        } else if (unitId === 61) {
          lessonExercises = generateUnit61Exercises(lessonId, data);
        } else if (unitId === 62) {
          lessonExercises = generateUnit62Exercises(lessonId, data);
        } else {
          lessonExercises = generateDynamicExercises(unitId, lessonId, data);
        }
        if (data[0].type || data[0].id) {
          questions.push(...data);
        } else {
          questions.push(...buildInterleavedQuestions(unitId, lessonId, data));
        }
      }
    }

    // İsim tamlaması ünitesinde çoklu boşluk doldurma sorusu ekle
    if (unitId === 3 && lIdx === 0) {
      questions.push({
        id: `u3l1_multi_fb`,
        type: "multiple-fill-blank",
        prompt: "Fill in the Blanks:",
        sentence: "An objection is a ___ between smth that a ___ wants and something that you, in their opinion, ___.",
        corrects: ["clash", "customer", "dislike"],
        translation: "İtiraz, müşterinin istediği şey ile sizin onun fikrince hoşlanmadığınız şey arasındaki çatışmadır."
      });
    }

    let subtitle = topic.subtitles[lIdx] || "Ekstra Pratik";
    let lessonPages = null;
    if (subtitle) {
      const pageMatch = subtitle.match(pageRegex);
      if (pageMatch) {
        lessonPages = pageMatch[1];
      }
      subtitle = subtitle
        .replace(/\s*\(Sayfa\s*\d+(?:-\d+)?\)/gi, "")
        .replace(/Takımlarına/g, "Yapılarına")
        .replace(/takımlarına/g, "yapılarına")
        .replace(/Takımları/g, "Yapıları")
        .replace(/takımları/g, "yapıları")
        .replace(/Takımı/g, "Yapısı")
        .replace(/takımı/g, "yapısı")
        .replace(/Strüktürleri/g, "Yapıları")
        .replace(/strüktürleri/g, "yapıları")
        .replace(/Strüktürü/g, "Yapısı")
        .replace(/strüktürü/g, "yapısı")
        .replace(/Strüktürel/g, "Yapısal")
        .replace(/strüktürel/g, "yapısal")
        .replace(/Strüktür/g, "Yapı")
        .replace(/strüktür/g, "yapı");
      if (unitId === 32) {
        subtitle = subtitle.replace(/^[A-Z]\.\s*/, "");
      }
    }
    const currentDisplayLessonNum = lIdx + 1;

    lessons.push({
      id: lessonId,
      displayId: currentDisplayLessonNum,
      title: [6, 1, 2, 7, 8, 33, 9, 10, 11, 3, 4, 5, 60, 61, 62, 12, 14, 15, 16, 18, 19, 20, 31, 23, 24, 32, 26, 28, 29, 30, 13, 17, 21, 22, 102, 101, 103, 40, 41, 70].includes(unitId) ? `${currentDisplayLessonNum}. ${((unitId === 40 || unitId === 28) ? subtitle.replace(/^\d+:\s*/, "") : subtitle.replace(/^(?:\d+[\.:\s]*)+/g, "").replace(/^(?:Giriş\.|[A-Za-z][.)])\s*/i, "").trim())}` : `${currentDisplayLessonNum}. Ders`,
      originalLessonId: lessonId,
      subtitle: [6, 1, 2, 7, 8, 33, 9, 10, 11, 3, 4, 5, 60, 61, 62, 12, 14, 15, 16, 18, 19, 20, 31, 23, 24, 32, 26, 28, 29, 30, 13, 17, 21, 22, 102, 101, 103, 40, 70].includes(unitId) ? "" : subtitle,
      icon: (lessonId === 901) ? (lessonIcons[7] || "📖") :
        (lessonId === 902) ? (lessonIcons[8] || "📖") :
          (lessonId === 906) ? (lessonIcons[19] || "📖") :
            (lessonId === 915) ? (lessonIcons[47] || "📖") :
              (lessonIcons[lessonId - 1] || "📖"),
      unitId: unitId,
      questions: questions,
      exercises: lessonExercises,
      formula: topic.formulas && topic.formulas[lIdx] ? topic.formulas[lIdx].formula : "",
      example: topic.formulas && topic.formulas[lIdx] ? topic.formulas[lIdx].example : "",
      description: topic.formulas && topic.formulas[lIdx] ? (topic.formulas[lIdx].description || "") : "",
      pages: lessonPages
    });
  }
  globalLessonCounter = startLessonId + numLessons;
});

// Toplam soru sayısını hesaplayan yardımcı
function getTotalQuestions() {
  return lessons.reduce((sum, l) => sum + l.questions.length, 0);
}

